import{_ as r,o as l,c as t,a4 as a}from"./chunks/framework.DzJZdBQK.js";const b=JSON.parse('{"title":"简易ZeroNet站点","description":"","frontmatter":{"date":"2017-12-11T20:36:57","title":"简易ZeroNet站点","categories":["zeronet"],"tags":["ZeroNet"]},"headers":[{"level":2,"title":"ZeroHello","slug":"zerohello","link":"#zerohello","children":[]},{"level":2,"title":"ZeroBorad","slug":"zeroborad","link":"#zeroborad","children":[{"level":3,"title":"消息公告示例","slug":"消息公告示例","link":"#消息公告示例","children":[]},{"level":3,"title":"工作原理","slug":"工作原理","link":"#工作原理","children":[]}]},{"level":2,"title":"ZeroBlog","slug":"zeroblog","link":"#zeroblog","children":[{"level":3,"title":"个人博客示例","slug":"个人博客示例","link":"#个人博客示例","children":[]},{"level":3,"title":"工作原理？","slug":"工作原理-1","link":"#工作原理-1","children":[]}]},{"level":2,"title":"ZeroTalk","slug":"zerotalk","link":"#zerotalk","children":[{"level":3,"title":"去中心化的，P2P论坛示例","slug":"去中心化的-p2p论坛示例","link":"#去中心化的-p2p论坛示例","children":[]},{"level":3,"title":"工作原理","slug":"工作原理-2","link":"#工作原理-2","children":[]}]},{"level":2,"title":"ZeroMail","slug":"zeromail","link":"#zeromail","children":[]},{"level":2,"title":"ZeroChat","slug":"zerochat","link":"#zerochat","children":[]},{"level":2,"title":"ZeroMe","slug":"zerome","link":"#zerome","children":[]},{"level":2,"title":"ReactionGIFs","slug":"reactiongifs","link":"#reactiongifs","children":[]}],"relativePath":"posts/zeronet/zeronet-3.md","filePath":"posts/zeronet/zeronet-3.md"}'),o={name:"posts/zeronet/zeronet-3.md"};function i(n,e,h,s,c,d){return l(),t("div",null,[...e[0]||(e[0]=[a('<h2 id="zerohello" tabindex="-1">ZeroHello <a class="header-anchor" href="#zerohello" aria-label="Permalink to &quot;ZeroHello&quot;">​</a></h2><p>ZeroNet的主页</p><ul><li>列出所有添加的站点：名称，节点数，修改时间</li><li>站点操作：更新，暂停，继续，删除</li><li>克隆站点转换成你的博客或者论坛</li><li>一键更新 <img src="http://zeronet.readthedocs.io/en/latest/img/zerohello.png" alt=""> 地址：<a href="http://127.0.0.1:43110/1HeLLo4uzjaLetFx6NH3PMwFP3qbRbTf3D" target="_blank" rel="noreferrer">1HeLLo4uzjaLetFx6NH3PMwFP3qbRbTf3D</a><a href="https://github.com/HelloZeroNet/ZeroHello" target="_blank" rel="noreferrer">源码</a></li></ul><h2 id="zeroborad" tabindex="-1">ZeroBorad <a class="header-anchor" href="#zeroborad" aria-label="Permalink to &quot;ZeroBorad&quot;">​</a></h2><h3 id="消息公告示例" tabindex="-1">消息公告示例 <a class="header-anchor" href="#消息公告示例" aria-label="Permalink to &quot;消息公告示例&quot;">​</a></h3><ul><li>通过授权码动态生成用户</li><li>实时消息更新</li></ul><h3 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h3><ul><li>你发送消息给站点所有者的机器人</li><li>机器人修改message.json文件，然后签名并发布给其他节点</li><li>如果网站的更新到达你的客户端，他就会显示在你的浏览器上。 <img src="http://zeronet.readthedocs.io/en/latest/img/zeroboard.png" alt=""> 地址：<a href="http://127.0.0.1:43110/1Gfey7wVXXg1rxk751TBTxLJwhddDNfcdp" target="_blank" rel="noreferrer">1Gfey7wVXXg1rxk751TBTxLJwhddDNfcdp</a><a href="https://github.com/HelloZeroNet/ZeroBoard" target="_blank" rel="noreferrer">源码</a></li></ul><h2 id="zeroblog" tabindex="-1">ZeroBlog <a class="header-anchor" href="#zeroblog" aria-label="Permalink to &quot;ZeroBlog&quot;">​</a></h2><h3 id="个人博客示例" tabindex="-1">个人博客示例 <a class="header-anchor" href="#个人博客示例" aria-label="Permalink to &quot;个人博客示例&quot;">​</a></h3><ul><li>内置内容编辑器</li><li>Markdown语法</li><li>代码高亮</li><li>只要网页就可以签名和发布网站</li></ul><h3 id="工作原理-1" tabindex="-1">工作原理？ <a class="header-anchor" href="#工作原理-1" aria-label="Permalink to &quot;工作原理？&quot;">​</a></h3><ul><li>你可以通过页面修改<code>data.json</code></li><li>点击<code>Sign &amp; Publsh new conent</code>按钮时会要求私钥（创建新站点时<a href="http://zeronet.readthedocs.io/en/latest/using_zeronet/create_new_site/" target="_blank" rel="noreferrer">生成</a>）</li><li>你的ZeroNet客户端签名新的，修改的文件并把文件发布到其他节点。</li><li>只要还有一个节点是活动的，你的站点就可以访问。 <img src="http://zeronet.readthedocs.io/en/latest/img/zeroblog.png" alt=""> 地址：<a href="http://127.0.0.1:43110/1BLogC9LN4oPDcruNz3qo1ysa133E9AGg8" target="_blank" rel="noreferrer">1BLogC9LN4oPDcruNz3qo1ysa133E9AGg8</a> 或者<a href="http://127.0.0.1:43110/blog.zeronetwork.bit" target="_blank" rel="noreferrer">blog.zeronetwork.bit</a><a href="https://github.com/HelloZeroNet/ZeroBlog" target="_blank" rel="noreferrer">源码</a></li></ul><h2 id="zerotalk" tabindex="-1">ZeroTalk <a class="header-anchor" href="#zerotalk" aria-label="Permalink to &quot;ZeroTalk&quot;">​</a></h2><h3 id="去中心化的-p2p论坛示例" tabindex="-1">去中心化的，P2P论坛示例 <a class="header-anchor" href="#去中心化的-p2p论坛示例" aria-label="Permalink to &quot;去中心化的，P2P论坛示例&quot;">​</a></h3><ul><li>创建，修改，删除主题和消息</li><li>主题和消息投票</li><li>仅有一次和站点所有者的联系，就是在请求修改网站授权的时候。</li><li>留言和内容修改直接会推送给其他节点</li><li>只有你可以签名和修改你的文件。</li><li>实时的消息显示</li></ul><h3 id="工作原理-2" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理-2" aria-label="Permalink to &quot;工作原理&quot;">​</a></h3><ul><li>要参与网站的互动，你需要从ZeroID提供者那里注册一个证书（一个加密签名）</li><li>有了证书之后，你就可以发布内容（消息，主题，投票）给其他节点了。 <a href="http://zeronet.readthedocs.io/en/latest/img/zerotalk.png" target="_blank" rel="noreferrer"></a> 地址：<a href="http://127.0.0.1:43110/1TaLkFrMwvbNsooF4ioKAY9EuxTBTjipT" target="_blank" rel="noreferrer">1TaLkFrMwvbNsooF4ioKAY9EuxTBTjipT</a> 或者<a href="http://127.0.0.1:43110/talk.zeronetwork.bit" target="_blank" rel="noreferrer">talk.zeronetwork.bit</a></li></ul><p><a href="https://github.com/HelloZeroNet/ZeroTalk" target="_blank" rel="noreferrer">源码</a></p><h2 id="zeromail" tabindex="-1">ZeroMail <a class="header-anchor" href="#zeromail" aria-label="Permalink to &quot;ZeroMail&quot;">​</a></h2><p>端到端加密，分布式，点对点消息站点。为了提高隐私安全使用了与比特消息类似的解决方案，这样就不会暴露收件人信息。</p><ul><li>使用ECISE用于私密传输，采用AES256进行消息编码。</li><li>当你第一次访问网站的时候，你的公钥会添加到你的数据文件中，这样其他人就可以给你发消息了。</li><li>每个人都尝试解密消息，这使得要找出消息接收人成为不可能，从而提高了隐私性。</li><li>为了减少消息负载和加快消息解密速度，我们重用了AES密钥，但是每次都会生成一个新的IV。 <img src="http://zeronet.readthedocs.io/en/latest/img/zeromail.png" alt=""> 地址:<a href="http://127.0.0.1:43110/1MaiL5gfBM1cyb4a8e3iiL8L5gXmoAJu27" target="_blank" rel="noreferrer">1MaiL5gfBM1cyb4a8e3iiL8L5gXmoAJu27</a>或者<a href="http://127.0.0.1:43110/mail.zeronetwork.bit" target="_blank" rel="noreferrer">mail.zeronetwork.bit</a><a href="https://github.com/HelloZeroNet/ZeroMail" target="_blank" rel="noreferrer">源码</a></li></ul><h2 id="zerochat" tabindex="-1">ZeroChat <a class="header-anchor" href="#zerochat" aria-label="Permalink to &quot;ZeroChat&quot;">​</a></h2><p>一个完整的网站用于演示如何使用ZeroNet在不到用不到时100行的代码创建一个server-less，SQL后台，实时更新的P2P聊天应用。</p><ul><li>选择ZeroID证书</li><li>用SQL数据库存储消息</li><li>实时创建和分布消息</li><li>实时更新消息 <img src="http://zeronet.readthedocs.io/en/latest/img/zerochat.png" alt=""> 地址：<a href="http://127.0.0.1:43110/1AvF5TpcaamRNtqvN1cnDEWzNmUtD47Npg" target="_blank" rel="noreferrer">1AvF5TpcaamRNtqvN1cnDEWzNmUtD47Npg</a> ZeroBlog上的教程：<a href="http://127.0.0.1:43110/Blog.ZeroNetwork.bit/?Post:43:ZeroNet+site+development+tutorial+1" target="_blank" rel="noreferrer">第1部分</a>,<a href="http://127.0.0.1:43110/Blog.ZeroNetwork.bit/?Post:46:ZeroNet+site+development+tutorial+2" target="_blank" rel="noreferrer">第2部分</a></li></ul><h2 id="zerome" tabindex="-1">ZeroMe <a class="header-anchor" href="#zerome" aria-label="Permalink to &quot;ZeroMe&quot;">​</a></h2><p>去中心化的，类Twitter的P2P社交网络。</p><ul><li>在ZeroMe的用户注册表中存储用户信息</li><li>将发布和留言存储在叫Hub的MergeSite中</li><li>通过选择文件来上传图片。</li><li>实时显示活动订阅 <img src="http://zeronet.readthedocs.io/en/latest/img/zerome.png" alt=""> 地址：<a href="http://127.0.0.1:43110/1MeFqFfFFGQfa1J3gJyYYUvb5Lksczq7nH" target="_blank" rel="noreferrer">1MeFqFfFFGQfa1J3gJyYYUvb5Lksczq7nH</a><a href="https://github.com/HelloZeroNet/ZeroMe" target="_blank" rel="noreferrer">源码</a></li></ul><h2 id="reactiongifs" tabindex="-1">ReactionGIFs <a class="header-anchor" href="#reactiongifs" aria-label="Permalink to &quot;ReactionGIFs&quot;">​</a></h2><p>选择文件示例，视频文件只有浏览器请求时才会下载。 <img src="http://zeronet.readthedocs.io/en/latest/img/reactiongifs.jpg" alt=""> 地址<a href="http://127.0.0.1:43110/1Gif7PqWTzVWDQ42Mo7np3zXmGAo3DXc7h" target="_blank" rel="noreferrer">1Gif7PqWTzVWDQ42Mo7np3zXmGAo3DXc7h</a><a href="https://github.com/HelloZeroNet/ReactionGIFs" target="_blank" rel="noreferrer">源码</a></p>',30)])])}const u=r(o,[["render",i]]);export{b as __pageData,u as default};
